#!/usr/bin/env node
/**
 * Copies the generated dataset, the Amiri font and the background art from the
 * Android project into the Flutter asset folders.
 *
 * Source of truth:
 *   mobile/android/app/src/main/assets/*.tsv          (generated by exportAssets.js, gitignored)
 *   mobile/android/app/src/main/assets/fonts/Amiri-Regular.ttf
 *   mobile/android/res/drawable-nodpi/{bg_hero.jpg, bg_page_light.jpg, bg_page_dark.jpg, calligraphy.png}
 *
 * Output:
 *   mobile/flutter/assets/data/*.tsv   (translations.tsv split into translations.<lang>.tsv)
 *   mobile/flutter/assets/fonts/Amiri-Regular.ttf
 *   mobile/flutter/assets/art/*
 *
 * Run from anywhere: `node mobile/flutter/tool/sync_assets.mjs`.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const flutterRoot = path.resolve(here, "..");
const repoRoot = path.resolve(flutterRoot, "..", "..");
const androidAssets = path.join(repoRoot, "mobile", "android", "app", "src", "main", "assets");
const drawables = path.join(repoRoot, "mobile", "android", "res", "drawable-nodpi");

const dataOut = path.join(flutterRoot, "assets", "data");
const fontOut = path.join(flutterRoot, "assets", "fonts");
const artOut = path.join(flutterRoot, "assets", "art");
for (const dir of [dataOut, fontOut, artOut]) fs.mkdirSync(dir, { recursive: true });

const report = [];
const copy = (from, to) => {
  if (!fs.existsSync(from)) throw new Error(`Missing source file: ${from}`);
  fs.copyFileSync(from, to);
  report.push({ file: path.relative(flutterRoot, to), bytes: fs.statSync(to).size });
};

// Plain TSV files copied as-is.
for (const name of ["chapters.tsv", "quran.tsv", "translation-meta.tsv", "lexicon.tsv", "provenance.tsv", "quran-meta.tsv"]) {
  const source = path.join(androidAssets, name);
  // quran-meta.tsv is committed under scripts/data as the fallback source.
  const fallback = path.join(repoRoot, "mobile", "android", "scripts", "data", name);
  copy(fs.existsSync(source) ? source : fallback, path.join(dataOut, name));
}

// translations.tsv (lang \t verse_key \t text) is split per language so the app
// can load only the languages it needs.
const translationsFile = path.join(androidAssets, "translations.tsv");
if (!fs.existsSync(translationsFile)) throw new Error(`Missing source file: ${translationsFile}`);
const byLanguage = new Map();
const content = fs.readFileSync(translationsFile, "utf8");
let start = 0;
while (start < content.length) {
  let end = content.indexOf("\n", start);
  if (end < 0) end = content.length;
  const line = content.slice(start, end).replace(/\r$/, "");
  start = end + 1;
  if (!line) continue;
  const tab = line.indexOf("\t");
  if (tab <= 0) continue;
  const lang = line.slice(0, tab);
  if (!/^[a-z]{2,3}$/.test(lang)) throw new Error(`Unexpected language code in translations.tsv: ${lang}`);
  let lines = byLanguage.get(lang);
  if (!lines) {
    lines = [];
    byLanguage.set(lang, lines);
  }
  lines.push(line);
}
// Remove stale per-language files before writing the current set.
for (const existing of fs.readdirSync(dataOut)) {
  if (/^translations\.[a-z]{2,3}\.tsv$/.test(existing)) fs.unlinkSync(path.join(dataOut, existing));
}
for (const [lang, lines] of [...byLanguage.entries()].sort()) {
  const target = path.join(dataOut, `translations.${lang}.tsv`);
  fs.writeFileSync(target, `${lines.join("\n")}\n`, "utf8");
  report.push({ file: path.relative(flutterRoot, target), bytes: fs.statSync(target).size, rows: lines.length });
}

copy(path.join(androidAssets, "fonts", "Amiri-Regular.ttf"), path.join(fontOut, "Amiri-Regular.ttf"));
for (const name of ["bg_hero.jpg", "bg_page_light.jpg", "bg_page_dark.jpg", "calligraphy.png"]) {
  copy(path.join(drawables, name), path.join(artOut, name));
}

for (const row of report) {
  const extra = row.rows ? ` (${row.rows} rows)` : "";
  console.log(`${row.file.padEnd(44)} ${String(row.bytes).padStart(10)} bytes${extra}`);
}
console.log(`Synced ${report.length} files into ${path.relative(repoRoot, flutterRoot)}/assets`);
